when.set-body:
@{
          var response = context.Response.Body.As();
          var text = string.Join("", ((JArray)response["output"] ?? new JArray())
            .Where(item => (string)item["type"] == "message")
            .SelectMany(item => (JArray)item["content"] ?? new JArray())
            .Where(part => (string)part["type"] == "output_text")
            .Select(part => (string)part["text"]));
          return new JObject(new JProperty("agent", "__AGENT__"), new JProperty("answer", text)).ToString();
        }
